import { NextRequest, NextResponse } from "next/server";
import { PASSWORD_SESSION_COOKIE_NAME, PASSWORD_SESSION_MAX_AGE, verifyChatPassword, hasSameOriginRequest } from "@/lib/password-auth";

export function GET() {
  return NextResponse.json({ ok: false, error: "Use POST" }, { status: 405 });
