export async function POST(request: NextRequest) {
  const origin = request.headers.get("origin");
  const forwardedHost = request.headers.get("x-forwarded-host");
  const host = request.headers.get("host");

  if ((origin && !hasSameOriginRequest(request)) || !forwardedHost && !host) {
    return NextResponse.json({ ok: false, error: "Invalid origin" }, { status: 403 });
  }

  const { password } = await request.json().catch(() => ({}));

  if (!verifyChatPassword(password)) {
    return NextResponse.json({ ok: false, error: "Invalid password" }, { status: 401 });
  }

  const token = makePasswordSessionToken();
  const response = NextResponse.json({ ok: true });
  response.cookies.set(PASSWORD_SESSION_COOKIE_NAME, token, {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    maxAge: PASSWORD_SESSION_MAX_AGE,
    path: "/",
  });

  return response;
}
